;------------------------------------------------------------------------------
; reset_sub  ($E000)
; Sub CPU reset (released by the main CPU's SRESET_OFF write).
; DP = $10, S = $1D80; wait for $11 in $0800 from the main CPU;
; checksum $A000-$BFFF, $C000-$DFFF, $E000-$FFFF (byte sums must be
; 0; failures leave '6', '5', '4' in $0801, shown by the service
; mode); answer $22 in $0800; 256 times write $6001 (IRQ on) and
; $500F (unmapped in MAME; meaning unknown); enable interrupts and
; enter the task scheduler.
; Vector: RESET
;------------------------------------------------------------------------------
reset_sub:
E000: 1A 10           ORCC   #$10            ; mask IRQ
E002: 86 10           LDA    #$10
E004: 1F 8B           TFR    A,DP
E006: 10 CE 1D 80     LDS    #$1D80          ; sub stack below $1D80

wait_main_handshake:
E00A: B6 08 00        LDA    sub_handshake   ; wait for the main CPU's $11
                                             ; [$0800]
E00D: 81 11           CMPA   #$11
E00F: 26 F9           BNE    wait_main_handshake
E011: 4F              CLRA
E012: 7F 08 01        CLR    sub_rom_error   ; [$0801]
E015: 8E A0 00        LDX    #dat_A000       ; checksum $A000-$BFFF

lE018:
E018: AB 80           ADDA   ,X+
E01A: 8C C0 00        CMPX   #dat_C000
E01D: 26 F9           BNE    lE018
E01F: 81 00           CMPA   #$00
E021: 27 05           BEQ    lE028
E023: 86 36           LDA    #$36            ; '6': $A000 ROM bad
E025: B7 08 01        STA    sub_rom_error   ; [$0801]

lE028:
E028: CC 00 00        LDD    #$0000

lE02B:
E02B: AB 80           ADDA   ,X+
E02D: 8C E0 00        CMPX   #reset_sub
E030: 26 F9           BNE    lE02B
E032: 81 00           CMPA   #$00
E034: 27 05           BEQ    lE03B
E036: 86 35           LDA    #$35            ; '5': $C000 ROM bad
E038: B7 08 01        STA    sub_rom_error   ; [$0801]

lE03B:
E03B: CC 00 00        LDD    #$0000

lE03E:
E03E: AB 80           ADDA   ,X+
E040: 8C 00 00        CMPX   #$0000
E043: 26 F9           BNE    lE03E
E045: 81 00           CMPA   #$00
E047: 27 05           BEQ    lE04E
E049: 86 34           LDA    #$34            ; '4': $E000 ROM bad
E04B: B7 08 01        STA    sub_rom_error   ; [$0801]

lE04E:
E04E: 86 22           LDA    #$22            ; handshake answer
E050: B7 08 00        STA    sub_handshake   ; [$0800]

irq_on_loop:
E053: B7 60 01        STA    IRQ_ON_SUB      ; IRQ on (odd address) [$6001]
E056: B7 50 0F        STA    $500F           ; unmapped write, 256 times
E059: 5A              DECB
E05A: 26 F7           BNE    irq_on_loop
E05C: 1C EF           ANDCC  #$EF            ; interrupts on
E05E: 7E E0 EC        JMP    task_dispatch_sub

;------------------------------------------------------------------------------
; irq_sub  ($E061)
; Sub CPU vblank IRQ.
;   - acknowledge (even VINTON address = IRQ off);
;   - copy the sub's sprites from the shadow buffers ($0E00-$0EE1 +
;     banks $1600/$1E00; bit 7 of the flag byte = in use) into sprite
;     RAM from slot 1 ($0F82) up to slot 39, mirrored when the screen
;     is flipped; unused slots get Y/flags $F000 (parked off-screen);
;   - frame_sync = $11 and wait for the main CPU's IRQ to answer $22
;     (the two IRQ handlers meet here every frame);
;   - IRQ on (odd VINTON address), RTI.
; Vector: SWI3, SWI2, FIRQ, IRQ, SWI, NMI
;------------------------------------------------------------------------------
irq_sub:
E061: B7 60 80        STA    IRQ_OFF_SUB     ; acknowledge (even address)
                                             ; [$6080]
E064: CE 0E 00        LDU    #sprite_shadow_1 ; [#$0E00]
E067: 8E 0F 82        LDX    #SPRITE_RAM_1+$02 ; [#$0F82]

lE06A:
E06A: 11 83 0E E2     CMPU   #$0EE2
E06E: 27 5A           BEQ    irq_sub_disable_rest
E070: A6 C9 10 01     LDA    $1001,U
E074: 84 80           ANDA   #$80
E076: 26 04           BNE    lE07C
E078: 33 42           LEAU   $2,U
E07A: 20 EE           BRA    lE06A

lE07C:
E07C: 96 2C           LDA    <flip_screen    ; [$102C]
E07E: 27 31           BEQ    lE0B1
E080: 86 E0           LDA    #$E0
E082: E6 C9 10 00     LDB    $1000,U
E086: E7 89 10 00     STB    $1000,X
E08A: C4 20           ANDB   #$20
E08C: 27 02           BEQ    lE090
E08E: 86 D0           LDA    #$D0

lE090:
E090: A0 C9 08 00     SUBA   $0800,U
E094: A7 89 08 00     STA    $0800,X
E098: A6 C9 10 01     LDA    $1001,U
E09C: 84 01           ANDA   #$01
E09E: E6 C9 08 01     LDB    $0801,U
E0A2: 83 01 A0        SUBD   #$01A0
E0A5: 43              COMA
E0A6: 53              COMB
E0A7: E7 89 08 01     STB    $0801,X
E0AB: A7 89 10 01     STA    $1001,X
E0AF: 20 10           BRA    lE0C1

lE0B1:
E0B1: EC C9 10 00     LDD    $1000,U
E0B5: ED 89 10 00     STD    $1000,X
E0B9: EC C9 08 00     LDD    $0800,U
E0BD: ED 89 08 00     STD    $0800,X

lE0C1:
E0C1: EC C1           LDD    ,U++
E0C3: ED 81           STD    ,X++
E0C5: 8C 0F D0        CMPX   #$0FD0
E0C8: 26 A0           BNE    lE06A

irq_sub_disable_rest:
E0CA: 8C 0F D0        CMPX   #$0FD0
E0CD: 27 0F           BEQ    irq_sub_sync
E0CF: CC F0 00        LDD    #$F000
E0D2: ED 89 10 00     STD    $1000,X
E0D6: ED 89 08 00     STD    $0800,X
E0DA: ED 81           STD    ,X++
E0DC: 20 EC           BRA    irq_sub_disable_rest

irq_sub_sync:
E0DE: 86 11           LDA    #$11            ; sub frame done
E0E0: 97 AF           STA    <frame_sync     ; [$10AF]

lE0E2:
E0E2: 96 AF           LDA    <frame_sync     ; wait for the main CPU's IRQ
                                             ; [$10AF]
E0E4: 81 22           CMPA   #$22
E0E6: 26 FA           BNE    lE0E2
E0E8: B7 60 81        STA    IRQ_ON_SUB      ; IRQ on again [$6081]
E0EB: 3B              RTI

;------------------------------------------------------------------------------
; task_dispatch_sub  ($E0EC)
; The sub CPU's scheduler: jump through
; sub_mode_task_lists[game_mode][sub_task]. Tasks end with
; INC <$7A / JMP task_dispatch_sub; the last one
; (task_end_frame_sub) waits for the IRQ and restarts the list.
; Jumped to from: $B02E, $B3CE, $B3E3, $B545, $B633, $B8A9, $B92D, $BB81,
; $BC37, $BC9B, $BD15, $BF24, $BF88, $E05E, $E187, $E1C3, $E290, $E4BA, $E631,
; $E6D0, $E7EA, $E8BC, $EAAB, $ECE1, $ED1C, $F200, $F5FB, $F608, $F6D6, $F886,
