task_dispatch_sub:
E0EC: CE E0 F9        LDU    #sub_mode_task_lists
E0EF: 96 2F           LDA    <game_mode      ; A = game mode, B = task [$102F]
E0F1: D6 7A           LDB    <sub_task       ; [$107A]
E0F3: 48              ASLA
E0F4: EE C6           LDU    A,U
E0F6: 58              ASLB
E0F7: 6E D5           JMP    [B,U]           ; run the task [table
